<script setup lang="ts">import{ref,onMounted}from'vue';import AppShell from'../components/AppShell.vue';import{api}from'../services/api';const u=ref<any>({});onMounted(async()=>{try{u.value=(await api('/api/auth/me')).user}catch{}})</script><template><AppShell><main class="page"><div class="title">Cá nhân</div><div class="card profile"><v-avatar size="84" color="#fdecef"><v-icon size="46" color="#8b0d24">mdi-account</v-icon></v-avatar><h2>{{u.full_name||'Người dùng'}}</h2><p class="muted">{{u.username}} · {{u.role_code}}</p><v-divider/><div class="line"><span>Phòng ban</span><b>{{u.department_id||'ITCA'}}</b></div><div class="line"><span>Vai trò</span><b>{{u.role_code}}</b></div></div></main></AppShell></template><style scoped>.profile{max-width:600px;margin-top:20px;text-align:center}.line{display:flex;justify-content:space-between;padding:15px 0;border-bottom:1px solid #eee;text-align:left}</style>
